"use strict";
const menuButton = document.querySelector('.nav-toggle');
const nav = document.querySelector('#navigation');
function closeMenu(){nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false');}
menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&menuButton.getAttribute('aria-expanded')==='true'){closeMenu();menuButton.focus();}});
window.matchMedia('(min-width:701px)').addEventListener('change',closeMenu);
const filters=document.querySelectorAll('[data-filter]');
filters.forEach(button=>button.addEventListener('click',()=>{filters.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let count=0;document.querySelectorAll('.project').forEach(card=>{const show=button.dataset.filter==='all'||card.dataset.category===button.dataset.filter;card.hidden=!show;if(show)count++;});document.querySelector('#filter-status').textContent=`${count} concept project${count===1?'':'s'} shown`;}));
const projects={orbit:{title:'Orbit study',copy:'A study of contrast, balance and implied movement. Overlapping forms suggest an orbit without using animation or video. Adapt this composition into a case-study cover or a motion-design direction.',alt:'Violet and orange orbital sculpture'},signal:{title:'Signal study',copy:'An angular visual language built from a rising waveform. Warm gradients and a technical grid explore how a simple shape can become a recognizable editorial signature.',alt:'Orange angular wave illustration'},still:{title:'Still study',copy:'A quiet architectural composition. The open arch and repeated horizon lines explore negative space, rhythm and depth. Use as a starting point for an original visual narrative.',alt:'Teal arch above repeated horizon lines'}};
const dialog=document.querySelector('#project-dialog');let opener;
document.querySelectorAll('.project-open').forEach(button=>button.addEventListener('click',()=>{opener=button;const key=button.dataset.project;const project=projects[key];document.querySelector('#dialog-title').textContent=project.title;document.querySelector('#dialog-copy').textContent=project.copy;const img=document.querySelector('#dialog-image');img.src=`assets/${key}.svg`;img.alt=project.alt;dialog.showModal();document.body.style.overflow='hidden';document.querySelector('.dialog-close').focus();}));
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',event=>{const rect=dialog.getBoundingClientRect();if(event.target===dialog&&(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom))dialog.close();});
dialog.addEventListener('close',()=>{document.body.style.overflow='';opener?.focus();});
